+//     by a corrupt or unreadable v2 copy
+func ResolveCommittedReaderForCheckpoint( //nolint:ireturn // Caller needs polymorphic v1/v2 reader.
+	ctx context.Context,
+	checkpointID id.CheckpointID,
+	v1Store *GitStore,
+	v2Store *V2GitStore,
+	preferCheckpointsV2 bool,
