363	func hasCurrentFullSessionArtifacts(repo *git.Repository, v2Store *checkpoint.V2GitStore, cpID id.CheckpointID, sessionIdx int) (bool, error) {
364		_, rootTreeHash, err := v2Store.GetRefState(plumbing.ReferenceName(paths.V2FullCurrentRefName))
365		if err != nil {
366			return false, nil //nolint:nilerr // Missing /full/current ref means required artifacts are absent.
367		}
368	
369		rootTree, err := repo.TreeObject(rootTreeHash)
370		if err != nil {
371			return false, fmt.Errorf("failed to read /full/current tree: %w", err)
372		}
373	
374		sessionPath := fmt.Sprintf("%s/%d", cpID.Path(), sessionIdx)
375		sessionTree, err := rootTree.Tree(sessionPath)
376		if err != nil {
377			return false, nil //nolint:nilerr // Missing session path means artifacts are absent, not a hard error.
378		}
379	
380		hasTranscript := false
381		for _, entry := range sessionTree.Entries {
382			if entry.Name == paths.V2RawTranscriptFileName || strings.HasPrefix(entry.Name, paths.V2RawTranscriptFileName+".") {
383				hasTranscript = true
384				break
385			}
386		}
387		if !hasTranscript {
388			return false, nil
389		}
390	
391		if _, err := sessionTree.File(paths.V2RawTranscriptHashFileName); err != nil {
392			return false, nil //nolint:nilerr // Missing content hash indicates incomplete /full/current artifacts.
393		}
394	
395		return true, nil
396	}
